import json,urllib.request,urllib.error
T=open("/root/nocodb-token.txt").read().strip()
def g(u):
    try:
        r=urllib.request.Request("http://127.0.0.1:8080"+u,headers={"xc-token":T})
        f=urllib.request.urlopen(r,timeout=20)
        return f.getcode(), f.read()
    except urllib.error.HTTPError as e:
        return e.code, b""
    except Exception as e:
        return 0, str(e)[:70].encode()
c,b=g("/api/v2/meta/nocodb/info")
try:
    j=json.loads(b); print("версія:",j.get("version"),"| тип БД:",j.get("mainSubDomain") or j.get("databaseType") or "?")
except Exception: print("info:",c,b[:200])
c,b=g("/api/v2/meta/bases/")
BID=""
try:
    L=json.loads(b).get("list",[])
    BID=L[0]["id"]; print("баз:",len(L),"| id:",BID)
except Exception: print("bases:",c,b[:150])
TID="m58xsjo6at01ohl"
tests=[
 ("журнал змін (audit)","/api/v2/meta/bases/%s/audits?limit=1"%BID),
 ("журнал змін v1","/api/v1/db/meta/projects/%s/audits?limit=1"%BID),
 ("версії записів (revisions)","/api/v2/meta/bases/%s/revisions"%BID),
 ("права на таблицю","/api/v2/meta/bases/%s/permissions"%BID),
 ("вебхуки на Диспетчеризації","/api/v2/meta/tables/%s/hooks"%TID),
 ("власні ролі","/api/v2/meta/bases/%s/roles"%BID),
